                </button>
                <div
                    :id="data.settings?.collapse_mobile ? 'ecom-modal-block' : ''"
                    class="ecom-modal-block--mobile ecom-filter-modal"
                >
                    <div
                        class="ecom-modal-content--mobile ecom-scroll_bar"
                        :class="data?.settings?.collapse_mobile ? 'ecom-modal-content' : ''"
                    >
                        <div
                            v-if="data.settings.collapse_mobile"
                            class="modal-header"
                        >
                            <span
                                id="ecom-modal-close"
                                class="ecom-collapse-close ecom-filter-modal-close"
                                :class="data.settings.collapse_mobile ? 'ecom-collapse-close--mobile': ''"
                            >
                                <svg
                                    xmlns="http://www.w3.org/2000/svg"
                                    class="w-6 h-6"
                                    fill="none"
                                    viewBox="0 0 24 24"
                                    stroke="currentColor"
                                >
                                    <path
                                        stroke-linecap="round"
                                        stroke-linejoin="round"
                                        stroke-width="2"
                                        d="M6 18L18 6M6 6l12 12"
                                    />
                                </svg>
                            </span>
                        </div>

                        <!-- <div v-if="show_sub_menu" class="ecom-shopify_menu" v-html="liquid('linklists')" :data-show-all="show_all_items_menu??false"></div> -->

                        <span
                            class="ecom-collection__filters-heading"
                            v-html="lang(data.settings.title, 'filter_title')"
                        />
                        <form
                            class="ecom-collection__filters-form ecom-click"
                            :data-filter-id="data.id"
                            data-stopdrag="true"
                            v-html="liquid('filters')"
                        />
                    </div>
                </div>
            </div>
            <div
                v-if="data.settings.filter_type == 'dropdown'"
                class="ecom-collection__filters-container ecom-collection__filters-dropdown"
            >
                <button
                    id="button_menu_block"
                    class="ecom-button-filter-collapse ecom-filter-btn-toggle"
                    :class="data.settings.collapse_mobile ? 'button_menu_block--mobile' : ''"
                    type="button"
                >
                    <span
                        v-if="data.settings?.icon"
                        class="ecom-filter-collapse-icon"
                        v-html="data.settings?.icon?.value"
                    />
                    <span v-html="lang(data.settings?.title, 'filter_title')" />
                </button>
                <div
                    :id="data.settings?.collapse_mobile ? 'ecom-modal-block' : ''"
                    class="ecom-modal-block--mobile ecom-filter-modal"
                >
                    <div
                        class="ecom-modal-content--mobile ecom-scroll_bar"
                        :class="data.settings.collapse_mobile ? 'ecom-modal-content' : ''"
                    >
                        <div
                            v-if="data.settings.collapse_mobile"
                            class="modal-header"
                        >
                            <span
                                id="ecom-modal-close"
                                class="ecom-collapse-close ecom-filter-modal-close"
                                :class="data.settings?.collapse_mobile? 'ecom-collapse-close--mobile'  : ''"
                            >
                                <svg xmlns="http://www.w3.org/2000/svg"
                                    class="w-6 h-6"
                                    fill="none"
                                    viewBox="0 0 24 24"
                                    stroke="currentColor"
                                >
                                    <path
                                        stroke-linecap="round"
                                        stroke-linejoin="round"
                                        stroke-width="2"
                                        d="M6 18L18 6M6 6l12 12"
                                    />
                                </svg>
                            </span>
                        </div>
                        <!-- <div v-if="show_sub_menu" class="ecom-shopify_menu" v-html="liquid('linklists')" :data-show-all="show_all_items_menu??false"></div> -->
                        <span
                            class="ecom-collection__filters-heading"
                            v-html="lang(data.settings.title, 'filter_title')"
                        />
                        <form
                            method="GET"
                            class="ecom-collection__filters-form ecom-click"
                            :data-filter-id="data.id"
                            data-stopdrag="true"
                            v-html="liquid('filters')"
                        />
                    </div>
                </div>
            </div>
            <div
                v-if="data.settings?.filter_type == 'push_down'"
                class="ecom-collection__filters-container ecom-collection__filters-push_down"
                :data-mobile="data.settings?.collapse_mobile ? 'mobile': ''"
            >
                <button
                    id="button_menu_block"
                    type="button"
                    :class="data.settings.collapse_mobile ? 'button_menu_block--mobile' : ''"
                    class="ecom-flex ecom-filter-btn-toggle"
                >
                    <span
                        v-if="data.settings?.icon"
                        class="ecom-filter-collapse-icon"
                        v-html="data.settings.icon?.value"
                    />
                    <span v-html="data.settings.title" />
                </button>
                <!-- <div class="ecom-filter-push_down"
                    :class="data.settings.collapse_mobile ? 'ecom-filter-mobile' : ''"
                > -->
                <div
                    :id="data.settings?.collapse_mobile ? 'ecom-modal-block' : ''"
                    class="ecom-modal-block--mobile ecom-filter-modal"
                >
                    <div
                        class="ecom-modal-content--mobile ecom-scroll_bar"
                        :class="data.settings.collapse_mobile ? 'ecom-modal-content' : ''"
                    >
                        <div
                            v-if="data.settings.collapse_mobile"
                            class="modal-header"
                        >
                            <span
                                id="ecom-modal-close"
                                class="ecom-collapse-close ecom-filter-modal-close"
                                :class="data.settings.collapse_mobile ? 'ecom-collapse-close--mobile': ''"
                            >
                                <svg
                                    xmlns="http://www.w3.org/2000/svg"
                                    class="w-6 h-6"
                                    fill="none"
                                    viewBox="0 0 24 24"
                                    stroke="currentColor"
                                >
                                    <path
                                        stroke-linecap="round"
                                        stroke-linejoin="round"
                                        stroke-width="2"
                                        d="M6 18L18 6M6 6l12 12"
                                    />
                                </svg>
                            </span>
                        </div>
                        <!-- <div v-if="show_sub_menu" class="ecom-shopify_menu" v-html="liquid('linklists')" :data-show-all="show_all_items_menu??false"></div> -->
                        <form
                            class="ecom-collection__filters-form ecom-collection__filters-form-collapse ecom-click ecom-scroll_bar"
                            :data-filter-id="data.id"
                            data-stopdrag="true"
                            v-html="liquid('filters')"
                        />
                    </div>
                </div>
            </div>
        </div>
        <Liquid v-if="exporting && page_type == 'search'" :data="conditionSearchPage.end" />
    </div>
</template>

<script>
import { Liquid, Javascript, Element } from '@/mixins';
export default {
    name: 'CollectionFilter',
    presets:false,
    docs: 'https://help.ecomposer.io/docs/elements/collection-elements/filter/',
    mixins: [Liquid, Javascript, Element],
    props: {
        data: {
            type: Object,
            default () {
                return {}
            }
        }
    },
    data(){
        return {
            jsreactives: [
                    "filter_type",
                    "show_all_items_menu",
                    "collapse_mobile",
                    "accordion_close",
                    "link_list",
                    "hide_zero"
                ]
            }
        },
        computed: {
            csrContext() {
                const section = this.shopifyWrapper;
                const type = section?.shopify_type;

                if (!type) return null;

                const context = {
                    type,
                    handle: section?.data?.settings?.[type]?.value || null,
                    withFilters: true
                }

                if (this.show_sub_menu) {
                    context.linklistData = this.data?.settings?.link_list;
                }

                return context;
            },
            canMultipleLanguages() {
                return this.getPermission('translates',false);
            },
            isRightSide(){
                return this.data?.settings?.filter_type === "collapse" && this.data?.settings?.collapse_filter_position &&  this.data.settings.collapse_filter_position === 'right'? true: '';
            },
            page_type () {
                return this.$store.getters['page/params'].page;
            },
            listMenu() {
                return `
                    <${this.data.settings?.use_accordion &&this.data.settings.filter_type !== 'dropdown' && this.data.settings?.filter_type !== 'push_down' ? 'details': 'div'}
                                ${this.data.settings?.accordion_open ? ` open ` : ``}
                                class="${this.data.settings && this.data.settings.use_accordion &&this.data.settings.filter_type !== 'dropdown' && this.data.settings?.filter_type !== 'push_down' ? ' ecom-collection__filters-group-not__dropdown': ' ecom-collection__filters-group-dropdown'} ecom-collection__filters-group ecom-collection__filters-group-lists" data-attrs-max="${this.data.settings && this.data.settings.number_max ? this.data.settings.number_max : 5 }">
                        <summary class="ecom-collection__filters-group-summary">
                            <div class="ecom-collection__filters-group-header">
                                <span class="ecom-collection__filters-group-summary--title">${this.lang(this.data.settings?.menu_label, 'menu_label')}</span>
                                ${this.show_dropdown_arrow ?
                                    `<div class="ecom-icon-filter-close">${this.data.settings?.collapse_icon ? this.data.settings.collapse_icon.value : `<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 384 512\" fill=\"currentColor\"><path d=\"M362.7 203.9l-159.1 144c-6.125 5.469-15.31 5.469-21.44 0L21.29 203.9C14.73 197.1 14.2 187.9 20.1 181.3C26.38 174.4 36.5 174.5 42.73 180.1L192 314.5l149.3-134.4c6.594-5.877 16.69-5.361 22.62 1.188C369.8 187.9 369.3 197.1 362.7 203.9z\"></path></svg>`}</div>
                                     <div class="ecom-icon-filter-open">${this.data.settings?.expand_icon ? this.data.settings.expand_icon.value : `<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 384 512\" fill=\"currentColor\"><path d=\"M363.9 330.7c-6.271 6.918-16.39 6.783-22.62 1.188L192 197.5l-149.3 134.4c-6.594 5.877-16.69 5.361-22.62-1.188C14.2 324.1 14.73 314 21.29 308.1l159.1-144c6.125-5.469 15.31-5.469 21.44 0l159.1 144C369.3 314 369.8 324.1 363.9 330.7z\"></path></svg>`}</div>`
                                        :
                                    ``
                                }
                            </div>
                        </summary>
                        <div class="ecom-collection__filters-group--display">
                            {%- capture link_handle -%}${this.link_list ? this.link_list : ''}{%- endcapture -%}
                            {%- unless link_handle == empty -%}
                                {%- assign menu = linklists[link_handle] -%}
                                <ul class="ecom-shopify__menu-list">
                                    {% if menu and menu.links.size %}
                                        {% for link in menu.links %}
                                            {% assign child_link = link.links %}
                                            <li class="ecom-shopify__menu-item ecom-shopify__menu-item-type--{{link.type}} {% if child_link.size > 0 %}ecom-shopify__menu-item--has-children{% endif %} {% if link.active or link.child_active %} ecom-shopify__menu-item--active ecom-text-active {% endif %}">
                                                <div class="ecom-menu_item ecom-items {% if link.active or link.child_active %} ecom-item-active {% endif %}">
                                                    <a class="ecom-menu_title ecom-items--text" href="{{link.url}}" title="{{link.title | escape }}">
                                                        {{link.title}}
                                                    </a>
                                                    {%- if link.levels > 0 -%}
                                                        <div class="ecom-menu_icon">
                                                            <div class="ecom-items--icon ecom-menu_icon--normal">
                                                                ${this.icon_menu ? this.icon_menu.value : ''}
                                                            </div>
                                                            <div class="ecom-items--icon ecom-menu_icon--active">
                                                                ${this.icon_menu_active ? this.icon_menu_active.value : ''}
                                                            </div>
                                                        </div>
                                                    {%- endif -%}
                                                </div>
                                                {% if child_link.size > 0 %}
                                                    <ul class="ecom-shopify__menu-sub-menu" data-menu-size="{{child_link.size}}" data-menu-level="{{child_link.level}}"  style="{% if link.child_active %} max-height: 100%; {% endif %}">
                                                        {% for child in child_link %}
                                                            {% assign grand_link = child.links %}
                                                            <li class="ecom-shopify__menu-child-link-item ecom-shopify__menu-child-link-item-type--{{child.type}} {% if grand_link.size > 0 %}ecom-shopify__menu-child-link-item--has-children{% endif %} {% if child.active or child.child_active%} ecom-shopify__menu-child-link-item--active ecom-text-active{% endif %}" >
                                                                <div class="ecom-menu_item ecom-items">
                                                                    <a class="ecom-menu_title ecom-items--text" href="{{child.url}}" title="{{child.title | escape }}">
                                                                        {{child.title}}
                                                                    </a>
                                                                    {%- if child.levels > 0 -%}
                                                                        <div class="ecom-menu_icon">
                                                                            <div class="ecom-items--icon ecom-menu_icon--normal">
                                                                                ${this.icon_menu ? this.icon_menu.value : ''}
                                                                            </div>
                                                                            <div class="ecom-items--icon ecom-menu_icon--active">
                                                                                ${this.icon_menu_active ? this.icon_menu_active.value : ''}
                                                                            </div>
                                                                        </div>
                                                                    {%- endif -%}
                                                                </div>
                                                                {% if grand_link.size > 0 %}
                                                                    <ul class="ecom-shopify__menu-sub-menu" data-menu-size="{{grand_link.size}}" data-menu-level="{{child_link.level}}">
                                                                        {% for grand in grand_link %}
                                                                            <li class="ecom-shopify__menu-grand-link-item ecom-menu_item ecom-items ecom-shopify__menu-grand-link-item-type--{{grand.type}} {% if grand.active or grand.child_active %}ecom-shopify__menu-grand-link-item--active ecom-text-active{% endif %}">
                                                                                <a class="ecom-menu_title ecom-items--text" href="{{grand.url}}" title="{{grand.title | escape }}">
                                                                                    {{grand.title}}
                                                                                </a>
                                                                            </li>
                                                                        {% endfor %}
                                                                    </ul>
                                                                {%- endif -%}
                                                            </li>
                                                        {% endfor %}
                                                    </ul>
                                                {% endif %}
                                            </li>
                                        {% endfor %}
                                    {% endif %}
                                </ul>
                            {% else %}
                                <p>Select a menu to show</p>
                            {%- endunless -%}
                        </div>
                    </${this.data.settings?.use_accordion &&this.data.settings.filter_type !== 'dropdown' && this.data.settings?.filter_type !== 'push_down' ? 'details': 'div'}>
                `
            },
            conditionSearchPage() {
                return {
                    start: `{% if request.page_type == 'search' %}
                                {% liquid
                                    assign has_products = false

                                    for item in search.results
                                        if item.object_type == 'product'
                                            assign has_products = true
                                            break
                                        endif
                                    endfor
                                %}
                                {% if has_products %}
                    `,
                    end: `{% endif %} {% endif %}`
                }
            },
            liquids () {
                return {
                    filters: {
                        code: `
                        <!--EComposer-custom-liquid-filters-${this.data.id.split('-').pop()}-->
                        {% if template contains '.' %}
                            <input type="hidden" name="view" value="{{template | split: '.' | last }}" />
                        {% endif %}
                        {% if request.page_type == 'search' %}
                            {% assign results = search %}
                        {% else %}
                            {% assign results = collection %}
                        {% endif %}
                        {%- assign sort_by = results.sort_by | default: results.default_sort_by -%}
                        {%- if results.results_count != blank -%}
                            {%- assign ecom_filter_count = results.results_count -%}
                        {%- else -%}
                            {%- assign ecom_filter_count = results.products_count -%}
                        {%- endif -%}
                        <span class="ecom-filter-total-count" data-total="{{ ecom_filter_count }}" style="display:none;"></span>
                        {% assign color_option_name = '${this.data.settings && this.data.settings.option_name ? this.data.settings.option_name : '' }' | handleize %}
                        {% assign colors = shop.metafields.ecomposer.colors %}
                        {% capture icon_caret%}
                            <svg aria-hidden="true" focusable="false" role="presentation" class="icon icon-caret" viewBox="0 0 10 6">
                                <path fill-rule="evenodd" clip-rule="evenodd" d="M9.354.646a.5.5 0 00-.708 0L5 4.293 1.354.646a.5.5 0 00-.708.708l4 4a.5.5 0 00.708 0l4-4a.5.5 0 000-.708z" fill="currentColor">
                            </svg>
                        {% endcapture%}
                        {% capture close_icon %}
                            <span class="ecom-colletion-filters--close-icon">
                                <svg xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false" role="presentation" fill="currentColor" viewBox="0 0 18 17">
                                    <path d="M.865 15.978a.5.5 0 00.707.707l7.433-7.431 7.579 7.282a.501.501 0 00.846-.37.5.5 0 00-.153-.351L9.712 8.546l7.417-7.416a.5.5 0 10-.707-.708L8.991 7.853 1.413.573a.5.5 0 10-.693.72l7.563 7.268-7.418 7.417z" fill="currentColor"/>
                                </svg>
                            </span>
                        {% endcapture %}
                        ${this.data?.settings?.show_applied_filters
                                ? `
                                ${!this.exporting ? `{% if EComBuilderMode %}
                                    <div class="ecom-collection__filters-applied-block" data-filter-id="${this.data.id}">
                                        <div class="ecom-collection__filters-applied-heading">
                                            ${this.lang( this.data.settings.applied_title, 'applied_title' )}
                                        </div>
                                        <div class="ecom-collection-filters--active_values">
                                            <ul class="ecom-collection-filters--active_values-list" role="list">
                                                ${
                                                    this.data.settings.show_filter_result_count ?
                                                        `
                                                            <li class="ecom-collection__filters-group-result-count ecom-filter-count ecom-al_center">
                                                                <div class="ecom-collection__filters-group-list-item-result" href="#">${this.data.settings.result_count_text ? this.data.settings.result_count_text.replace('{{count}}', 10) : '10 Results Found'}</div>
                                                            </li>
                                                        `
                                                    : ''
                                                }
                                                {% for filter in results.filters %}
                                                    {% if filter.type == 'list' %}
                                                        {% for value in filter.values  %}
                                                            <li class="ecom-collection__filters-group-list-item ecom-al_center">
                                                                <a href="{{value.url_to_remove}}" title="{{value.label}}">{{ value.label | escape }} {{close_icon}}</a>
                                                            </li>
                                                        {% endfor %}
                                                        {% break %}
                                                    {% endif %}
                                                {% endfor %}
                                            </ul>
                                        </div>
                                    </div>
                                {% endif %}` : ''}

                                {%- for filter in results.filters -%}
                                    {%- if  filter.active_values.size > 0 or filter.min_value.value != nil or filter.max_value.value != nil -%}
                                        {%- assign has_filter = true -%}
                                        {%- break -%}
                                    {%- endif -%}
                                {%- endfor -%}
                                {%- if has_filter -%}
                                <div class="ecom-collection__filters-applied-block" data-filter-id="${this.data.id}">
                                    <div class="ecom-collection__filters-applied-heading">
                                        ${this.lang( this.data.settings.applied_title, 'applied_title' )}
                                    </div>
                                    <div class="ecom-collection-filters--active_values">
                                        <ul class="ecom-collection-filters--active_values-list" role="list">

                                            ${
                                                this.data.settings.show_filter_result_count ?
                                                    `
                                                    <li class="ecom-collection__filters-group-result-count ecom-filter-count ecom-al_center" data-count="{{results.results_count}}">
                                                        {%- liquid
                                                            if results.results_count != blank
                                                                assign count = results.results_count
                                                            else
                                                                 assign count = results.products_count
                                                            endif
                                                        -%}
                                                        <div class="ecom-collection__filters-group-list-item-result">
                                                            ${this.canMultipleLanguages ? `${this.lang(this.data.settings.result_count_text, 'result_count_text', { count: 'count'})}` : this.data.settings.result_count_text}
                                                        </div>
                                                    </li>
                                                    `
                                                : ''
                                            }
                                            {%- for filter in results.filters -%}
                                                {%- if filter.active_values.size > 0 -%}
                                                    {% for value in filter.active_values  %}
                                                        <li class="ecom-collection__filters-group-list-item ecom-al_center">
                                                            <a class="ecom-collection__filters-group-list-item-clear" href="{{value.url_to_remove}}" title="{{value.label}}">{{ value.label | escape }} {{close_icon}}</a>
                                                        </li>
                                                    {% endfor %}
                                                {% endif %}

                                                {% if filter.type == "price_range" %}
                                                {%- if filter.min_value.value != nil or filter.max_value.value != nil -%}
                                                    <li class="ecom-collection__filters-group-list-item ecom-al_center">
                                                        <a class="ecom-collection__filters-group-list-item-clear" href="{{filter.url_to_remove}}">
                                                            {%- if filter.min_value.value -%}{{ filter.min_value.value | money }}{%- else -%}{{ 0 | money }}{%- endif -%}-{%- if filter.max_value.value -%}{{ filter.max_value.value | money }}{%- else -%}{{ filter.range_max | money }}{%- endif -%}
                                                            {{close_icon}}
                                                        </a>
                                                    </li>

                                                {%- endif -%}
                                            {% endif %}
                                            {% endfor %}
                                            <li class="ecom-collection__filters-group-list-item ecom-al_center">
