                    let list = $el.querySelectorAll('.ecom-collection__filters-group-list');

                    list.forEach((l) => {
                        if (l.childNodes.length) {
                            l.closest('.ecom-collection__filters-group').classList.remove(
                                'ecom-d-none'
                            );
                        }
                    });
                // trigger hidden_radio before submit
                function trigger_radio() {
                    this.querySelector(
                        ".ecom-collection__filters-radio--input-hidden"
                    ).checked = true;
                }
                // Use $el scope instead of document to avoid affecting other Filter elements
                let range_price_item = $el.querySelectorAll('.ecom-collection__filters-group-radio');
                range_price_item.forEach((item) => {
                    item.addEventListener("click", trigger_radio);
                });
                const closeAllOther = this.settings.accordion_close ?? false;
                if (closeAllOther && (this.settings.filter_type == 'collapse' || (this.settings.filter_type == 'block' && this.settings.use_accordion))) {
                    const detailsElements = $el.querySelectorAll('.ecom-collection__filters-group');
                    if (detailsElements.length === 0) return;
                    detailsElements.forEach(function(details, index) {
                        if(index !== 0) {
                            details.removeAttribute('open');
                        };
                        details.addEventListener('click', function() {
                            detailsElements.forEach(function(otherDetails) {
                                if (otherDetails !== details) {
                                    otherDetails.removeAttribute('open');
                                }
                            });
                        });
                    });
                }
                //toggle
                function handleClickOutSide(e) {
                    let element = e.target;
                    do {
                        if(element && element.classList && element.classList.contains('ecom-collection__filters-group--display')){
                            return;
                        }
                        element = element.parentNode;
                    }while(element);
                    if(!element || !element.classList.contains('ecom-collection__filters-group--display')) {
                        let details = $el.querySelectorAll('.ecom-filter-dropdown-desktop .ecom-collection__filters-group .ecom-collection__filters-group-summary');
                        if(details.length > 0) {
                            details.forEach(
                                (item) =>
                                    item
                                        .closest('.ecom-collection__filters-group')
                                        .classList.contains('active') &&
                                    item
                                        .closest('.ecom-collection__filters-group')
                                        .classList.remove('active')
                            );
                        }
                        document.removeEventListener('click', handleClickOutSide)
                    }

                }
                function toggleDropdown () {
                        $el.querySelector('.ecom-collection__filters-dropdown') && $el.querySelector('.ecom-collection__filters-dropdown').classList.add(
                            'ecom-filter-dropdown-desktop'
                        );
                        let details = $el.querySelectorAll(
                            '.ecom-filter-dropdown-desktop .ecom-collection__filters-group .ecom-collection__filters-group-summary'
                        );
                        if (!details) {
                            return;
                        }
                        details.forEach((item) => {
                            let group = item.closest('.ecom-collection__filters-group');
                            let numMax = group.dataset.attrsMax;
                            let items = group.querySelectorAll(
                                '.ecom-collection__filters-group-list-item-max'
                            );
                            let popup = group.querySelector('.ecom-collection__filters-group--display ');
                            let btnMore = group.querySelector('.ecom-more-filter');
                            if (btnMore) {
                                btnMore.addEventListener('click', () => {
                                    showItem(items);
                                    btnMore.style.display = 'none';
                                });
                            }
                            if (items.length > 0 && numMax) {
                                numMax = parseInt(numMax);
                                showItem(items, numMax);
                            }

                            if(close_filter){if(group.classList.contains('active')) group.classList.remove('active')};
                            item.addEventListener('click', () => {

                                if (!group.classList.contains('active')) {
                                    document.removeEventListener('click', handleClickOutSide)
                                    details.forEach(
                                        (item) =>
                                            item
                                                .closest('.ecom-collection__filters-group')
                                                .classList.contains('active') &&
                                            item
                                                .closest('.ecom-collection__filters-group')
                                                .classList.remove('active')
                                    );
                                    if(popup) {
                                        setTimeout(function(){
                                            document.addEventListener('click', handleClickOutSide);
                                        }, 200)
                                        group.classList.add('active');
                                        const {left, right} = group.getBoundingClientRect();
                                        if(window.innerWidth - left < 300) {
                                            popup.style.left = `-${300 - (window.innerWidth - left - 10)}px`
                                        }
                                    }
                                } else {
                                    group.classList.remove('active');
                                }
                            });
                        });
                    }

                function showItem (list, max) {
                    list.forEach((item, index) => {
                        if (max === undefined) {
                            item.style.display = 'block';
                        } else {
                            if (index < max) {
                                item.style.display = 'block';
                            } else {
                                item.style.display = 'none';
                            }
                        }
                    });
                }

                    const collapseMobile = this.settings.collapse_mobile;
                    if (this.settings.filter_type == 'dropdown') {
                        toggleDropdown();
                    }

                    // Use class selectors instead of ID selectors to support multiple Filter elements
                    const modal = $el.querySelector('.ecom-filter-modal'),
                                btn = $el.querySelector('.ecom-filter-btn-toggle'),
                                filter_core_block = modal ? modal.closest('div.ecom-core.core__block') : '',
                                filter_core_column = modal ? modal.closest('div.ecom-column.ecom-core') : '',
                                span = $el.querySelector('.ecom-filter-modal-close');

                    const isMobile = window.matchMedia('only screen and (max-width: 1024px)');
                    //isMobile.addEventListener('change', conlapseCallback);
                    if (collapseMobile && isMobile.matches) {
                        conlapseCallback(isMobile);
                    }

                    function openSidebarFilter() {
                        if(!modal) return;
                        modal.style.display = 'block';
                        //fix z-index on Editor
                        filter_core_block ? (filter_core_block.style.zIndex = '99') : '';
                        filter_core_column ? (filter_core_column.style.zIndex = '99') : '';

                        //add Filter opened class to body
                        document.querySelector('body').classList.add('ecom-filter-opened');

                    }
                    function closeSidebarFilter() {
                        if(!modal) return;
                        modal.style.display = 'none';
                        document.querySelector('html').style.overflow = 'inherit';
                        document.body.style.overflow = 'inherit';
                        //fix z-index on Editor
                        filter_core_block ? (filter_core_block.style.zIndex = '1') : '';
                        filter_core_column ? (filter_core_column.style.zIndex = '1') : '';

                        setTimeout(function(){
                            document.querySelector('body').classList.remove('ecom-filter-opened');
                        }, 500);
                    }

                    // Click outside modal handler - scoped to this filter's modal
                    function handleModalOutsideClick(e) {
                        if (e.target === modal) {
                            closeSidebarFilter();
                        }
                    }

                    function conlapseCallback (isMobile) {
                        // When user clicks button, open Modal
                        let content = $el.querySelectorAll('.ecom-collection__filters-group--display');
                        if (isMobile.matches) {
                            if (_this.settings.collapse_mobile && modal && btn && span) {
                                modal ? (modal.style.display = 'none') : '';
                                if (_this.settings.filter_type == 'dropdown') {
                                    content.forEach((item) => {
                                        item.style.position = 'relative'
                                    })
                                }
                                btn.addEventListener('click', () => {
                                    document.querySelector('html').style.overflow = 'hidden';
                                    document.body.style.overflow = 'hidden';
                                    openSidebarFilter()
                                });

                                // When user clicks Close (x), close Modal
                                span.addEventListener('click', () => {
                                    closeSidebarFilter()
                                });

                                // When user clicks anywhere outside of the Modal, close Modal
                                // Use modal's own click event instead of window to avoid conflicts
                                modal.addEventListener('click', handleModalOutsideClick);

                                //fix z-index on Editor
                                filter_core_block ? (filter_core_block.style.zIndex = '99') : '';
                                filter_core_column ? (filter_core_column.style.zIndex = '99') : '';
                            }
                        } else {
                            modal ? (modal.style.display = 'block') : '';
                            filter_core_block ? (filter_core_block.style.zIndex = '1') : '';
                            filter_core_column ? (filter_core_column.style.zIndex = '1') : '';
                            if (_this.settings.filter_type == 'dropdown') {
                                content && content.forEach((item) => {
                                    item.style.position = 'absolute'
                                })
                            }
                        }
                    }
                    // collapse
                    if (this.settings.filter_type == 'collapse' || this.settings.filter_type == 'push_down' && this.settings.collapse_mobile) {
                        // When user clicks button, open Modal
                        if(btn) {
                            btn.addEventListener('click', () => {
                                if(this.settings.filter_type == 'collapse') {
                                    document.querySelector('html').style.overflow = 'hidden';
                                    document.body.style.overflow = 'hidden';
                                }
                                openSidebarFilter()
                            });
                        }

                        // When user clicks Close (x), close Modal
                        if(span) {
                            span.addEventListener('click', () => {
                                closeSidebarFilter()
                            });
                        }

                        // When user clicks anywhere outside of the Modal, close Modal
                        // Use modal's own click event instead of window to avoid conflicts
                        if(modal) {
                            modal.addEventListener('click', handleModalOutsideClick);
                        }
                    }
                    if(this.settings.collapse_mobile && this.settings.open_collapse_mobile && isMobile.matches) {
                        $el.querySelectorAll('.ecom-collection__filters-group').forEach(function(item) {
                            item.classList.add('active');
                        })
                    }
                    // handle push_down abcd
                    let height = 0, interval = 0, counter = 0, flag = 0, duration = 15;

                    //#2 the slideUp
                    function slideUp(element) {
                        if(height === 0) {
                            element.style.maxHeight = "100%";
                        }
                        counter = height; //declare the value of "counter" variable
                        element.classList.remove('ecom-show--filter');
                        var subtractor = height/10;

                        //to hide the content of the element
                        element.style.overflow = "hidden";

                        //decreasing the height
                        interval = setInterval(function () {

                        counter -= subtractor;
                        if (counter > 0) {
                            element.style.maxHeight = counter + "px";
                        } else {
                            element.style.maxHeight = 0;
                            clearInterval(interval);
                        }
                        }, duration);

                    }

                    //#3 the slideDown
                    function slideDown(element) {
                        var adder = height/10; //the height is global variable

                        //iteratively increase the height
                        element.classList.add('ecom-show--filter');
                        interval = setInterval(function () {
                        counter += adder;
                        if (counter < height) {
                            element.style.maxHeight = counter + "px";
                        } else {
                            element.style.maxHeight = height + "px";
                            clearInterval(interval);
                        }
                        }, duration);

                    }
                    function handlePushDown(){
                        const push_down = $el.querySelector('.ecom-container-filter-list--wrapper[data-type="push_down"]');
                        if(push_down){
                            if(height === 0) {
                                push_down.style.maxHeight = "100%";
                            }
                            height = push_down.offsetHeight;
                            // if(isLive){
                                slideUp(push_down);
                                push_down.style.display = 'none';
                                push_down.style.opacity = '1';
                            // }else{
                            //     push_down.style.opacity = '1';
                            // }
                            btn.addEventListener('click', () => {
                                if(push_down.classList.contains('ecom-show--filter')){
                                    slideUp(push_down);

                                }
                                else {
                                    push_down.style.display = 'grid';
                                    slideDown(push_down);
                                }

                            });
                        }
                    }
                    handlePushDown();


                    function handlePriceSlider(reset = false) {
                        let minDollars = 1;
                        let maxDollars = 15000;

                        if (!$el.querySelector('.ecom-collection__filters-group-price')) {
                            return true;
                        }

                        let $max = $el.querySelector('.ecom-collection__filters-price-range-max'),
                            $min = $el.querySelector('.ecom-collection__filters-price-range-min');
                        // Use class selectors instead of ID selectors to support multiple Filter elements
                        let minSlider = $el.querySelector('.ecom-filter-input-min');
                        let maxSlider = $el.querySelector('.ecom-filter-input-max');

                        if(!minSlider || !maxSlider || !$min || !$max) return;

                        minDollars = parseFloat($min.getAttribute('min'));
                        maxDollars = parseFloat($max.getAttribute('max'));
                        if(reset === true) {
                            minSlider.value = minSlider.getAttribute('min');
                            maxSlider.value = maxSlider.getAttribute('max');
                            updateDollars();
                            return;
                        }
                        function formatMoney (number) {
                            return window.EComposer.formatMoney(number);
                        }

                        // Cache price display elements
                        const priceFromEl = $el.querySelector('.ecom-filter-price-from');
                        const priceToEl = $el.querySelector('.ecom-filter-price-to');

                        function updateDollars () {
                            let fromValue =
                                ((maxDollars - minDollars) * minSlider.value) / 100 + minDollars;
                            let toValue = ((maxDollars - minDollars) * maxSlider.value) / 100 + minDollars;
                            $min.value = fromValue.toFixed(2);
                            $max.value = toValue.toFixed(2);
                            if(priceFromEl) {
                                priceFromEl.innerHTML = `${formatMoney(Math.floor(fromValue * 100))}`;
                            }
                            if(priceToEl) {
                                priceToEl.innerHTML = `${formatMoney(Math.floor(toValue * 100))}`;
                            }
                        }
                        maxSlider.addEventListener('input', () => {
                            let minValue = parseInt(minSlider.value);
                            let maxValue = parseInt(maxSlider.value);

                            if (maxValue < minValue + 1) {
                                minSlider.value = maxValue - 1;

                                if (minValue === parseInt(minSlider.min)) {
                                    maxSlider.value = 1;
                                }
                            }
                            updateDollars();
                        });

                        minSlider.addEventListener('input', () => {
                            let minValue = parseInt(minSlider.value);
                            let maxValue = parseInt(maxSlider.value);

                            if (minValue > maxValue - 1) {
                                maxSlider.value = minValue + 1;

                                if (maxValue === parseInt(maxSlider.max)) {
                                    minSlider.value = parseInt(maxSlider.max) - 1;
                                }
                            }

                            updateDollars();
                        });
                    }

                    //Hanlde collapsible menu
                    function hanldeCollapsible() {
                        var coll = $el.querySelectorAll(".ecom-shopify__menu-item--has-children > .ecom-menu_item, .ecom-shopify__menu-child-link-item--has-children > .ecom-menu_item");
                        if(!coll) return;
                        var i;
                        var isDefaultShowAll = "false";
                        var ecom_shopify_menu = $el.querySelector(".ecom-shopify_menu");
                        if(ecom_shopify_menu && ecom_shopify_menu.dataset.showAll) {
                            var isDefaultShowAll = ecom_shopify_menu.dataset.showAll;
                        }


                        for (i = 0; i < coll.length; i++) {
                            if(isDefaultShowAll && isDefaultShowAll == "true") {
                                if(!coll[i].classList.contains('ecom-item-active')){
                                    activeCollapsible(coll[i]);
                                }
                            }
                            coll[i].addEventListener("click", function(e) {
                                e.preventDefault();
                                activeCollapsible(this);
                            });

                            function activeCollapsible(item) {
                                let content = item.nextElementSibling;
                                let parent_sub_menu = null;
                                if(item.classList.contains("ecom-item-active")) {
                                    item.classList.remove("ecom-item-active");
                                    if(content) {
                                        content.style.maxHeight = null;

                                        var child_menu_items = content.querySelectorAll('.ecom-menu_item');
                                        if(child_menu_items) {
                                            child_menu_items.forEach((item) => {
                                                var sibling_content = item.nextElementSibling;
                                                if(sibling_content) {
                                                    sibling_content.style.maxHeight = null;
                                                }
                                                item.classList.remove('ecom-item-active');
                                            });
                                        }

                                        parent_sub_menu = item.closest('.ecom-shopify__menu-sub-menu');
                                        if(parent_sub_menu) {
                                            parent_sub_menu.style.maxHeight = parseInt(parent_sub_menu.style.maxHeight) - content.scrollHeight + "px";
                                        }

                                    }
                                } else {
                                    item.classList.add("ecom-item-active");
                                    if (content) {
                                        parent_sub_menu = item.closest('.ecom-shopify__menu-sub-menu');
                                        if(parent_sub_menu) {
                                            parent_sub_menu.style.maxHeight = parseInt(parent_sub_menu.style.maxHeight) + content.scrollHeight + "px";
                                        }
                                        content.style.maxHeight = content.scrollHeight + "px";
                                    }
                                }
                            }
                        }
                    }

                    hanldeCollapsible();

                    const ecomAjaxFilter = (function() {
                        return {
                        searchParamsInitial: window.location.search.slice(1),
                        searchParamsPrev: window.location.search.slice(1),
                        init() {
                            const facetForms = $el.querySelectorAll('.ecom-collection__filters-form');
                            if(facetForms.length == 0) {
                                return;
                            }

                            const wrapper = facetForms[0].closest('.ecom-sections[data-section-id]');
                            const wrapper_product = facetForms[0].closest('.ecom-row.ecom-section');
                            if(!wrapper || !wrapper.dataset.sectionId) {
                                return;
                            }
                            this.facetForms = facetForms;
                            this.wrapper = wrapper;
                            this.sectionId = wrapper.dataset.sectionId;
                            this.wrapper_product = wrapper_product;
                            // Store filter element ID for matching applied blocks
                            this.filterId = _this.id;

                            this.debouncedOnSubmit = this.debounce((event) => {
                            this.onSubmitHandler(event);
                            }, 800);

                            this.facetForms.forEach($form => $form.addEventListener('input', this.debouncedOnSubmit.bind(this)))
                            this.handleRemoveFilter();
                            this.setListeners();
                        },

                        setListeners() {
                            const _self = this;
                            const onHistoryChange = (event) => {
                                const searchParams = event.state ? event.state.searchParams : _self.searchParamsInitial;
                                if (searchParams === _self.searchParamsPrev) return;
                                const url = `${window.location.pathname}?section_id=${_self.sectionId}&${searchParams}`;
                                _self.handleLoadProduct(url, searchParams, event, false);
                            };

                            // Singleton pattern: Only add one popstate listener per filter element
                            // Store reference to remove later if needed
                            if (!window.__ecomFilterPopstateHandlers) {
                                window.__ecomFilterPopstateHandlers = new Map();
                            }

                            // Remove existing handler for this filter if any (in case of re-init)
                            const existingHandler = window.__ecomFilterPopstateHandlers.get(this.filterId);
                            if (existingHandler) {
                                window.removeEventListener('popstate', existingHandler);
                            }

                            // Store and add new handler
                            window.__ecomFilterPopstateHandlers.set(this.filterId, onHistoryChange);
                            window.addEventListener('popstate', onHistoryChange);
                        },

                        debounce(fn, wait) {
                            let t;
                            return (...args) => {
                            clearTimeout(t);
                            t = setTimeout(() => fn.apply(this, args), wait);
                            };
                        },

                        onSubmitHandler(event) {
                            event.preventDefault();
                            const forms = [];

                            this.facetForms.forEach((form) => {
                            forms.push(this.createSearchParams(form));
                            });

                            let params = forms.join('&');
                            const urlParams = new URLSearchParams(new URL(window.location).search);
                            const desiredParams = ['q', 'type', 'options', 'sort_by'];
                            const filteredParams = {};

                            for (const [key, value] of urlParams) {
                                if (desiredParams.includes(key)) {
                                    filteredParams[key] = value;
                                }
                            }

                            // Generate new URL params
                            const newUrlParams = new URLSearchParams(filteredParams);

                            // New url get q type options sort_by
                            const newUrl = `&${newUrlParams.toString()}`;
                            if(newUrl && newUrl != '') params += newUrl;
                            const url = `${window.location.pathname}?section_id=${this.sectionId}&${params}`;
                            this.handleLoadProduct(url, params, event);
                            let filter_push_down = $el.querySelector('.ecom-container-filter-list--wrapper[data-type="push_down"]');
                            if(filter_push_down && close_filter) slideUp(filter_push_down);

                        },

                        createSearchParams(form) {
                            const formData = new FormData(form);
                            const seenPairs = {};
                            const uniqueParams = new URLSearchParams();

                            for (const [key, value] of formData.entries()) {
                                // Skip price range inputs if they have default/empty values
                                const input = form.querySelector(`[name="${key}"]`);
                                if (input && (input.classList.contains('ecom-collection__filters-price-range-min') ||
                                             input.classList.contains('ecom-collection__filters-price-range-max'))) {
                                    // Only include if value is different from placeholder/default and not empty
                                    if (!value || parseFloat(value) == 0 || parseFloat(value) == parseFloat(input.getAttribute('placeholder')) ||
                                        parseFloat(value) == parseFloat(input.getAttribute('min')) || parseFloat(value) == parseFloat(input.getAttribute('max'))) {
                                        continue;
                                    }
                                }
                                const pairKey = `${key}:${value}`;
                                // Unique key:value
                                if (!seenPairs[pairKey]) {
                                    uniqueParams.append(key, value);
                                    seenPairs[pairKey] = true;
                                }
                            }

                            return uniqueParams.toString();
                        },

                        handleLoadProduct(fetch_url, searchParams, event, updateURLHash = true) {
                            const _this = this;
                            this.searchParamsPrev = searchParams;

                            const loadProduct = async function(url) {
                            const response = await fetch(url, {
                                method: 'GET',
                                headers: {
                                'Content-Type': 'text/html'
                                },
                            });
                            return response.text();
                            }

                            // Add loading effect to ALL visible product wrappers (not just this filter's section)
                            // Must target .ecom-collection__product-wrapper because .ecom-collection__product-loading
                            // is a sibling of .ecom-collection__product-main, not a child
                            const productWrappers = document.querySelectorAll('.ecom-collection__product-wrapper');
                            productWrappers.forEach(wrapper => {
                                // Only add to visible wrappers (not hidden on current device)
                                const parentSection = wrapper.closest('.ecom-row.ecom-section');
                                if (parentSection) {
                                    const isHidden = (window.screen.width > 1024 && parentSection.classList.contains('hide-on-desktop'))
                                        || ((window.screen.width > 767 && window.screen.width <= 1024) && parentSection.classList.contains('hide-on-tablet'))
                                        || (window.screen.width <= 767 && parentSection.classList.contains('hide-on-mobile'));
                                    if (!isHidden) {
                                        wrapper.classList.add('ecom-doing-filter');
                                    }
                                }
                            });
                            // Also add to wrapper_product for backward compatibility
                            _this.wrapper_product.classList.add('ecom-doing-filter');

                            loadProduct(fetch_url).then(function(data) {
                                const dom = document.createElement('div');
                                dom.innerHTML = data;
                                let product_wrapper = null, idx = 0;
                                const class_wrapper = `.ecom-collection__product-main.ecom-collection_product_template_${page_type}`;
                                const product_wrappers = document.querySelectorAll(class_wrapper);
                                if(product_wrappers.length > 1){
                                    product_wrappers.forEach(function(wrapper, index) {
                                    if(product_wrapper) return;
                                     if(((window.screen.width > 1024 && !wrapper.closest('.hide-on-desktop'))
                                     || ((window.screen.width > 767 && window.screen.width <= 1024) && !wrapper.closest('.hide-on-tablet'))
                                     || (window.screen.width <= 767 && !wrapper.closest('.hide-on-mobile')))){
                                        product_wrapper = wrapper;
                                        idx = index
                                     }
                                   })
                                }
                                else {
                                    product_wrapper = product_wrappers[0];
                                }
                                if(!product_wrapper) {
                                    return;
                                }

                                //product_wrapper.scrollIntoView({behavior: "smooth"});
                                //Update product
                                // const domFacetForms = dom.querySelectorAll(`.${_this.wrapper_product.dataset.id} .ecom-collection__filters-form`);
                                // const dom_wrapper_product = domFacetForms[0].closest('.ecom-row.ecom-section');
                                let result_products = dom.querySelectorAll(class_wrapper);
                                // let result_products = dom_wrapper_product.querySelectorAll(class_wrapper);
                                // if(result_products.length == 0) {
                                //     result_products = dom.querySelectorAll(class_wrapper);
                                // }
                                product_wrapper.innerHTML = result_products && result_products[idx].innerHTML;
                                //Update URL
                                if(updateURLHash) _this.updateURLHash(searchParams)

                                // IMPORTANT: Call renderActiveFacets FIRST to ensure applied block exists
                                // before renderFilters tries to update the active values list inside it
                                _this.renderActiveFacets(dom);

                                // Then update filter groups
                                _this.renderFilters(dom, event);


                                product_wrapper.querySelector('.ecom-collection__product--wrapper-items') &&
                                product_wrapper.dispatchEvent(new CustomEvent('ecom-products-init',{
                                    detail: {
                                        wrapper: product_wrapper
                                    }
                                }))

                                // Dispatch event with filtered product count
                                const totalCountEl = dom.querySelector('.ecom-filter-total-count');
                                const totalCount = totalCountEl ? parseInt(totalCountEl.dataset.total) || 0 : 0;
                                document.dispatchEvent(new CustomEvent('ecom-filter-updated', {
                                    bubbles: true,
                                    detail: {
                                        count: totalCount,
                                        searchParams: searchParams
                                    }
                                }));
                            })
                            .finally(function() {
                            if(typeFilter === 'collapse' || ((typeFilter === 'block' || typeFilter ==='dropdown') && window.screen.width < 1025 && collapseMobile) ) {
                                if(close_filter) closeSidebarFilter();
                            }
                            if(window.EComposer && window.EComposer.initButtonWishlist) window.EComposer.initButtonWishlist();

                            // Remove loading effect from ALL product wrappers
                            document.querySelectorAll('.ecom-collection__product-wrapper').forEach(wrapper => {
                                wrapper.classList.remove('ecom-doing-filter');
                            });
                            // Also remove from wrapper_product for backward compatibility
                            _this.wrapper_product.classList.remove('ecom-doing-filter');
                            toggleDropdown();
                            })
                        },

                        updateURLHash(searchParams) {
                            history.pushState({ searchParams }, '', `${window.location.pathname}${searchParams && '?'.concat(searchParams)}`);
                        },

                        renderActiveFacets(html) {

                            // IMPORTANT: Update ALL filter elements on the page, not just the one that triggered ajax
                            // Find ALL applied blocks in the response
                            const allResultBlocks = html.querySelectorAll('.ecom-collection__filters-applied-block[data-filter-id]');

                            // Get unique filter IDs from response
                            const filterIds = new Set();
                            allResultBlocks.forEach(block => filterIds.add(block.dataset.filterId));

                            // Also get filter IDs from page (in case some filters have no applied values in response)
                            const allPageForms = this.wrapper.querySelectorAll('.ecom-collection__filters-form[data-filter-id]');
                            allPageForms.forEach(form => filterIds.add(form.dataset.filterId));

                            // Process each filter element
                            filterIds.forEach(filterId => {

                                const resultBlock = html.querySelector(`.ecom-collection__filters-applied-block[data-filter-id="${filterId}"]`);
                                const pageBlock = this.wrapper.querySelector(`.ecom-collection__filters-applied-block[data-filter-id="${filterId}"]`);
                                const pageForms = this.wrapper.querySelectorAll(`.ecom-collection__filters-form[data-filter-id="${filterId}"]`);


                                if (!pageBlock && resultBlock) {
                                    pageForms.forEach($form => {
                                        $form.prepend(resultBlock.cloneNode(true));
                                    });
                                } else if (pageBlock && resultBlock) {
                                    pageBlock.innerHTML = resultBlock.innerHTML;
                                } else if (pageBlock && !resultBlock) {
                                    pageBlock.remove();
                                }
                            });

                            // Search FilterValue elements in broader section scope (wrapper)
                            const filterValueElement = this.wrapper.querySelectorAll('.ecom-collection__filter-values');

                            if(filterValueElement.length > 0) {
                                // Use any applied block's active values content (they should all be the same)
                                const anyResultBlock = allResultBlocks[0];
                                const activeValuesContent = anyResultBlock
                                    ? anyResultBlock.querySelector('.ecom-collection-filters--active_values')
                                    : null;
                                filterValueElement.forEach((filter) => {
                                    if(activeValuesContent) {
                                        filter.innerHTML = activeValuesContent.innerHTML;
                                    } else {
                                        filter.innerHTML = '';
                                    }
                                })
                            }

                        },

                        renderFilters(dom, event) {

                            // IMPORTANT: Update ALL filter elements on the page, not just the one that triggered ajax
                            // This ensures all Filter elements stay in sync when one is used
                            const allFacetDetails = dom.querySelectorAll('.ecom-js-filter[data-filter-id][data-index]');

                            const matchesIndex = (element) => {
                                if(event.target === window) return false;
                                const jsFilter = event ? event.target.closest('.ecom-js-filter') : undefined;
                                return jsFilter ? (element.dataset.index === jsFilter.dataset.index && element.dataset.filterId === jsFilter.dataset.filterId) : false;
                            }

                            const facetsToRender = Array.from(allFacetDetails);
                            const countsToRender = facetsToRender.find(matchesIndex);

                            facetsToRender.forEach((element) => {
                                // Match by BOTH filter-id AND index to update the correct filter group
                                // Search in wrapper (broader scope) to update ALL Filter elements on page
                                const matchSelector = `.ecom-js-filter[data-filter-id="${element.dataset.filterId}"][data-index="${element.dataset.index}"]`;
                                const matchingFilters = this.wrapper.querySelectorAll(matchSelector);
                                matchingFilters.forEach(filter => {
                                    filter.innerHTML = element.innerHTML;
                                });
                            });

                            //Render filter active values for ALL filter elements
                            renderActiveFacetsForAll(dom, this.wrapper);

                            //render filter selected
                            if (countsToRender) renderCounts(countsToRender, event.target.closest('.ecom-js-filter'));


                            function renderActiveFacetsForAll(html, wrapper) {

                                // Find ALL applied blocks in the response and update their corresponding elements on page
                                const allAppliedBlocks = html.querySelectorAll('.ecom-collection__filters-applied-block[data-filter-id]');

                                allAppliedBlocks.forEach((sourceBlock) => {
                                    const filterId = sourceBlock.dataset.filterId;
                                    const selector = `.ecom-collection__filters-applied-block[data-filter-id="${filterId}"] .ecom-collection-filters--active_values-list`;

                                    const sourceActiveValues = sourceBlock.querySelector('.ecom-collection-filters--active_values-list');
                                    const targetActiveValues = wrapper.querySelector(selector);

                                    if (sourceActiveValues && targetActiveValues) {
                                        targetActiveValues.innerHTML = sourceActiveValues.innerHTML;
                                    }
                                });

                            }

                            function renderCounts(source, target) {
                                if(!target) return;

                                const targetElement = target.querySelector('.ecom-collection__filters-group--selected');
                                const sourceElement = source.querySelector('.ecom-collection__filters-group--selected');

                                const targetElementAccessibility = target.querySelector('.ecom-collection__filters-group-summary');
                                const sourceElementAccessibility = source.querySelector('.ecom-collection__filters-group-summary');
                                if (sourceElement && targetElement) {
                                    target.querySelector('.ecom-collection__filters-group--selected').outerHTML = source.querySelector('.ecom-collection__filters-group--selected').outerHTML;
                                }

                                if (targetElementAccessibility && sourceElementAccessibility) {
                                    target.querySelector('.ecom-collection__filters-group-summary').outerHTML = source.querySelector('.ecom-collection__filters-group-summary').outerHTML;
                                }
                            }
                        },

                        handleRemoveFilter() {
                            this.facetForms.forEach($form => {
                                $form.addEventListener('click', closeFilter.bind(this))
                            })

                            function closeFilter(event) {
                            if(event.target.closest('.ecom-collection__filters-group-list-item-clear') || event.target.closest('.ecom-collection__filters-group-reset-filter')) {
                                event.preventDefault();
                                const link = event.target.closest('.ecom-collection__filters-group-list-item-clear') || event.target.closest('.ecom-collection__filters-group-reset-filter');
                                if(!link.href) return;

                                let searchParams = link.href.indexOf('?') == -1 ? '' : link.href.slice(link.href.indexOf('?') + 1);
                                let sorting = window.location.search.match(/&sort_by=\S*/gm) && window.location.search.match(/&sort_by=\S*/gm).length && window.location.search.match(/&sort_by=\S*/gm)[0];
                                if(sorting) searchParams += sorting;
                                const url = `${window.location.pathname}?section_id=${this.sectionId}&${searchParams}`;
                                this.handleLoadProduct(url, searchParams, event);
                                handlePriceSlider(true);
                            }
                            }
                        }

                        }
                    })();

                    if (isLive) {
                        handlePriceSlider();

                        if(this.settings.enable_ajax) {
                            ecomAjaxFilter.init();
                        } else {
                            this.$el.querySelector('.ecom-collection__filters-form')
                            .addEventListener('change', function () {
                                if(page_type == 'search') {
                                    const urlParams = new URLSearchParams(new URL(window.location).search);
                                    const desiredParams = ['q', 'type', 'options', 'sort_by'];
                                    const filteredParams = {};

                                    for (const [key, value] of urlParams) {
                                        if (desiredParams.includes(key)) {
                                            filteredParams[key] = value;
                                        }
                                    }
                                    for (const key in filteredParams) {
                                        if (filteredParams.hasOwnProperty(key)) {
                                            const input = document.createElement('input');
                                            input.type = 'hidden'; // hoặc có thể sử dụng 'text' tùy thuộc vào yêu cầu
                                            input.name = key;
                                            input.value = filteredParams[key];
                                            this.appendChild(input);
                                        }
                                    }
                                    this.submit();
                                }
                                else {
                                    this.submit()
                                }
                            });


                        }
                    }
                };
            },

